def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(r for r, row in enumerate(grid) if all(x == 5 for x in row))
    top_colors = {x for row in grid[:sep] for x in row if x not in (0, 5)}
    color = next(c for c in top_colors if c != 1)

    def cells_of(c, rows):
        return [(r, col) for r in rows for col in range(w) if grid[r][col] == c]

    upper = cells_of(color, range(sep))
    lower = cells_of(1, range(sep + 1, h))
    minr, minc = min(r for r, c in upper), min(c for r, c in upper)
    base_r, base_c = min(r for r, c in lower), min(c for r, c in lower)

    out = [[0] * w for _ in range(9)]
    for r, c in upper:
        out[2 + r - minr][base_c + c - minc] = color
    for r, c in lower:
        out[5 + r - base_r][base_c + c - min(c for rr, c in lower)] = 1
    return out
